import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Skeleton } from "@/components/ui/skeleton";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import type { ImmuneTherapy, LaboratoryInvestigation, MultipleSclerosisDoseAdherence, NeurologicalInvestigation, PatientFollowUp, ProtocolInvestigation, RadiologicalInvestigation, ResearchFile } from "../../../drizzle/schema";
import { ArrowLeft, CheckCircle2, ClipboardCheck, FileImage, FileUp, FlaskConical, Info, ListChecks, Pill, Plus, Save, ShieldCheck, Trash2, UploadCloud } from "lucide-react";
import { useEffect, useState } from "react";
import { toast } from "sonner";
import { useLocation } from "wouter";

type Cohort = "stroke" | "multiple_sclerosis" | "abnormal_movements" | "guillain_barre" | "myasthenia_gravis" | "myelopathy" | "neuro_ophthalmology" | "cidp";
type Choice = [string, string];
type FormState = { researchId: string; cohort: Cohort; sex: "female" | "male" | "not_recorded"; ageAtEnrollment: string; ageAtOnset: string; consentStatus: "consented" | "pending" | "declined" | "withdrawn"; enrollmentStatus: "screened" | "enrolled" | "completed" | "withdrawn" | "ineligible"; clinicalStatus: "active" | "follow_up" | "completed" | "deceased" | "unknown"; dataQualityStatus: "draft" | "complete" | "query"; completenessStatus: "complete" | "incomplete" | "needs_review"; missingItems: string[]; completionOwnerUserId: string; primaryDiagnosis: string; briefClinicalHistory: string; positiveExaminationFindings: string; dischargeTreatment: string; immuneTherapies: ImmuneTherapy[]; msDoseAdherence: MultipleSclerosisDoseAdherence[]; clinicalData: Record<string, string>; radiologicalInvestigations: RadiologicalInvestigation[]; laboratoryInvestigations: LaboratoryInvestigation[]; neurologicalInvestigations: NeurologicalInvestigation[]; protocolInvestigations: ProtocolInvestigation[]; followUpVisits: PatientFollowUp[] };

const cohorts: Record<Cohort, string> = { stroke: "Stroke", multiple_sclerosis: "Multiple Sclerosis (MS)", abnormal_movements: "Abnormal Movements", guillain_barre: "Guillain–Barré Syndrome (GBS)", myasthenia_gravis: "Myasthenia Gravis (MG)", myelopathy: "Myelopathy", neuro_ophthalmology: "Neuro-ophthalmology", cidp: "CIDP & inflammatory neuropathy" };
const protocolLabels: Record<string, string> = { mri_brain_with_contrast: "Brain MRI with contrast", mri_spine: "Spine MRI", csf_oligoclonal_bands: "CSF oligoclonal bands", emg_ncs: "EMG / NCS", csf_analysis: "CSF analysis", fundus_examination: "Fundus examination", visual_fields_oct: "Visual fields / OCT", eeg: "EEG", evoked_potentials: "Evoked potentials", vascular_imaging: "Vascular imaging", cardiac_evaluation: "Cardiac evaluation", cervical_spine_imaging: "Cervical spine imaging", autoimmune_serology: "Autoimmune serology", infection_screening: "Infection screening", infection_exclusion_pre_immunotherapy: "Infection-exclusion review before immune therapy", chest_imaging_pre_immunotherapy: "Chest imaging before immune therapy", tuberculin_tb_screen_pre_immunotherapy: "Tuberculin / IGRA TB screen before immune therapy", varicella_immunity_pre_immunotherapy: "Varicella immunity (VZV immunoglobulin / serology)", neuropsychology: "Neuropsychology", tuberculosis_screening: "Tuberculin / TB screening", immune_therapy_safety: "Immune-therapy safety review", aqp4_mog_antibodies: "AQP4 / MOG antibodies", temporal_artery_assessment: "Temporal artery assessment", nerve_biopsy: "Nerve biopsy", peripheral_nerve_ultrasound: "Peripheral nerve ultrasound", stroke_severity_assessment: "NIHSS / mRS assessment", other: "Other protocol test" };
const missingItemChoices: Choice[] = [["consent", "Consent"], ["demographics", "Demographics"], ["clinical_history", "Brief clinical history"], ["positive_examination", "Positive examination"], ["clinical_classification", "Clinical classification"], ["radiology", "Radiology"], ["laboratory", "Laboratory"], ["neurological_investigations", "Neurological investigations"], ["protocol_checklist", "Protocol checklist"], ["immune_therapy", "Immune therapy"], ["discharge_treatment", "Discharge treatment"], ["follow_up", "Follow-up"], ["research_files", "Research files"], ["other", "Other"]];
const immuneCohorts: Cohort[] = ["multiple_sclerosis", "guillain_barre", "myasthenia_gravis", "myelopathy", "neuro_ophthalmology", "cidp"];

function clinicalDefaults(cohort: Cohort): Record<string, string> {
  if (cohort === "stroke") return { cohort, strokeType: "unknown", vascularTerritory: "unknown", reperfusionTherapy: "unknown", toastEtiology: "unknown", majorComplication: "unknown", strokeEvaluation: "unknown" };
  if (cohort === "multiple_sclerosis") return { cohort, diseaseCourse: "unknown", disabilityLevel: "unknown", relapseActivity: "unknown", diseaseModifyingTherapy: "unknown", msfcAssessed: "no", timed25FootWalkSeconds: "", nineHolePegTestSeconds: "", pasat3Score: "", tuberculinScreen: "not_done", chestTuberculosisScreen: "not_done", msEvaluation: "unknown" };
  if (cohort === "abnormal_movements") return { cohort, movementPhenotype: "unknown", distribution: "unknown", severity: "unknown", functionalImpact: "unknown", treatmentResponse: "unknown", movementEvaluation: "unknown" };
  if (cohort === "guillain_barre") return { cohort, variant: "unknown", disabilityScore: "unknown", ventilatorySupport: "unknown", treatment: "unknown", gbsEvaluation: "unknown" };
  if (cohort === "myasthenia_gravis") return { cohort, mgfaClass: "unknown", antibodyStatus: "unknown", thymomaStatus: "unknown", crisisHistory: "unknown", treatmentResponse: "unknown", mgEvaluation: "unknown" };
  if (cohort === "myelopathy") return { cohort, level: "unknown", cause: "unknown", upperMotorNeuronSigns: "unknown", lowerMotorNeuronFeatures: "unknown", bladderInvolvement: "unknown", myelopathyEvaluation: "unknown" };
  if (cohort === "neuro_ophthalmology") return { cohort, visualSyndrome: "unknown", laterality: "unknown", acuityChange: "unknown", afferentDefect: "unknown", diseaseClassification: "unknown", antibodyProfile: "not_done", linkedSystemicDisease: "unknown", neuroOphEvaluation: "unknown" };
  return { cohort, phenotype: "unknown", diagnosticPathway: "cidp", disabilityLevel: "unknown", emgNcsEvidence: "unknown", csfProteinStatus: "unknown", cidpEvaluation: "unknown" };
}
function protocolDefaults(cohort: Cohort): ProtocolInvestigation[] {
  const preImmuneTherapyScreening = ["infection_exclusion_pre_immunotherapy", "chest_imaging_pre_immunotherapy", "tuberculin_tb_screen_pre_immunotherapy", "varicella_immunity_pre_immunotherapy"];
  const codes: Record<Cohort, string[]> = { stroke: ["vascular_imaging", "cardiac_evaluation", "stroke_severity_assessment"], multiple_sclerosis: ["mri_brain_with_contrast", "csf_oligoclonal_bands", "evoked_potentials", "tuberculosis_screening", ...preImmuneTherapyScreening, "immune_therapy_safety"], abnormal_movements: ["mri_brain_with_contrast", "other"], guillain_barre: ["emg_ncs", "csf_analysis", "infection_screening", ...preImmuneTherapyScreening, "immune_therapy_safety"], myasthenia_gravis: ["autoimmune_serology", ...preImmuneTherapyScreening, "immune_therapy_safety"], myelopathy: ["mri_spine", "csf_analysis", "cervical_spine_imaging", ...preImmuneTherapyScreening], neuro_ophthalmology: ["fundus_examination", "visual_fields_oct", "mri_brain_with_contrast", "aqp4_mog_antibodies", "temporal_artery_assessment", ...preImmuneTherapyScreening], cidp: ["emg_ncs", "csf_analysis", "autoimmune_serology", "infection_screening", ...preImmuneTherapyScreening, "peripheral_nerve_ultrasound", "nerve_biopsy", "immune_therapy_safety"] };
  return codes[cohort].map(itemCode => ({ itemCode, status: "not_ordered", note: null }));
}
const defaults: FormState = { researchId: "", cohort: "stroke", sex: "not_recorded", ageAtEnrollment: "", ageAtOnset: "", consentStatus: "pending", enrollmentStatus: "screened", clinicalStatus: "unknown", dataQualityStatus: "draft", completenessStatus: "incomplete", missingItems: [], completionOwnerUserId: "unassigned", primaryDiagnosis: "", briefClinicalHistory: "", positiveExaminationFindings: "", dischargeTreatment: "", immuneTherapies: [], msDoseAdherence: [], clinicalData: clinicalDefaults("stroke"), radiologicalInvestigations: [], laboratoryInvestigations: [], neurologicalInvestigations: [], protocolInvestigations: protocolDefaults("stroke"), followUpVisits: [] };

export default function PatientEditor({ mode, recordId }: { mode: "create" | "edit"; recordId?: number }) {
  const [, navigate] = useLocation(); const utils = trpc.useUtils(); const [form, setForm] = useState<FormState>(defaults); const [fileCategory, setFileCategory] = useState<"radiology_image" | "radiology_report" | "laboratory_report" | "other">("radiology_image");
  const { data: record, isLoading, error } = trpc.registry.get.useQuery({ id: recordId ?? 0 }, { enabled: mode === "edit" && Boolean(recordId) }); const { data: owners = [] } = trpc.registry.assignableUsers.useQuery(); const { data: audit } = trpc.registry.auditTrail.useQuery({ id: recordId ?? 0 }, { enabled: mode === "edit" && Boolean(recordId) }); const { data: files = [] } = trpc.registry.files.useQuery({ patientRecordId: recordId ?? 0 }, { enabled: mode === "edit" && Boolean(recordId) });
  const create = trpc.registry.create.useMutation({ onSuccess: () => done("Research record created") }); const update = trpc.registry.update.useMutation({ onSuccess: () => done("Research record updated") }); const uploadFile = trpc.registry.uploadFile.useMutation({ onSuccess: () => { utils.registry.files.invalidate({ patientRecordId: recordId ?? 0 }); toast.success("Research file uploaded"); } });
  function done(message: string) { utils.registry.list.invalidate(); utils.registry.overview.invalidate(); toast.success(message); navigate("/registry"); }
  useEffect(() => { if (!record) return; setForm({ researchId: record.researchId, cohort: record.cohort as Cohort, sex: record.sex as FormState["sex"], ageAtEnrollment: String(record.ageAtEnrollment), ageAtOnset: record.ageAtOnset === null ? "" : String(record.ageAtOnset), consentStatus: record.consentStatus, enrollmentStatus: record.enrollmentStatus, clinicalStatus: record.clinicalStatus, dataQualityStatus: record.dataQualityStatus, completenessStatus: record.completenessStatus, missingItems: record.missingItems as string[], completionOwnerUserId: record.completionOwnerUserId ? String(record.completionOwnerUserId) : "unassigned", primaryDiagnosis: record.primaryDiagnosis, briefClinicalHistory: record.briefClinicalHistory ?? "", positiveExaminationFindings: record.positiveExaminationFindings ?? "", dischargeTreatment: record.dischargeTreatment ?? "", immuneTherapies: (record.immuneTherapies ?? []) as ImmuneTherapy[], msDoseAdherence: (record.msDoseAdherence ?? []) as MultipleSclerosisDoseAdherence[], clinicalData: Object.fromEntries(Object.entries(record.clinicalData as Record<string, unknown>).map(([key, value]) => [key, value == null ? "" : String(value)])), radiologicalInvestigations: record.radiologicalInvestigations as RadiologicalInvestigation[], laboratoryInvestigations: record.laboratoryInvestigations as LaboratoryInvestigation[], neurologicalInvestigations: record.neurologicalInvestigations as NeurologicalInvestigation[], protocolInvestigations: record.protocolInvestigations as ProtocolInvestigation[], followUpVisits: record.followUpVisits as PatientFollowUp[] }); }, [record]);
  const set = <K extends keyof FormState>(key: K, value: FormState[K]) => setForm(current => ({ ...current, [key]: value }));
  const setCohort = (cohort: Cohort) => setForm(current => ({ ...current, cohort, clinicalData: clinicalDefaults(cohort), protocolInvestigations: protocolDefaults(cohort), msDoseAdherence: cohort === "multiple_sclerosis" ? current.msDoseAdherence : [] }));
  const submit = () => { const numeric = (value: string) => value === "" ? null : Number(value); const clinical = { ...form.clinicalData, cohort: form.cohort, ...(form.cohort === "multiple_sclerosis" ? { timed25FootWalkSeconds: numeric(form.clinicalData.timed25FootWalkSeconds), nineHolePegTestSeconds: numeric(form.clinicalData.nineHolePegTestSeconds), pasat3Score: numeric(form.clinicalData.pasat3Score) } : {}) }; const payload: any = { ...form, researchId: form.researchId.toUpperCase(), ageAtEnrollment: Number(form.ageAtEnrollment), ageAtOnset: numeric(form.ageAtOnset), completionOwnerUserId: form.completionOwnerUserId === "unassigned" ? null : Number(form.completionOwnerUserId), briefClinicalHistory: form.briefClinicalHistory || null, positiveExaminationFindings: form.positiveExaminationFindings || null, dischargeTreatment: form.dischargeTreatment || null, clinicalData: clinical }; if (!Number.isInteger(payload.ageAtEnrollment)) return toast.error("Enter a valid age at enrolment."); if (mode === "create") create.mutate(payload); else update.mutate({ id: recordId, ...payload }); };
  const add = (section: "radiologicalInvestigations" | "laboratoryInvestigations" | "neurologicalInvestigations" | "followUpVisits") => { const templates: any = { radiologicalInvestigations: { modality: "mri", bodyRegion: "brain", keyFinding: "", lesionStatus: "indeterminate", reportReference: null }, laboratoryInvestigations: { testName: "hba1c", resultStatus: "unknown", resultSummary: null }, neurologicalInvestigations: { testName: "emg_ncs", resultStatus: "unknown", resultSummary: null, lowerMotorNeuronRelevant: false }, followUpVisits: { visitType: "routine", followUpStatus: "scheduled", outcome: "unknown", assessmentSummary: "", nextFollowUpPlan: null, timepoint: "unscheduled" } }; setForm(current => ({ ...current, [section]: [...(current[section] as any[]), templates[section]] })); };
  const updateArray = (section: "radiologicalInvestigations" | "laboratoryInvestigations" | "neurologicalInvestigations" | "followUpVisits" | "protocolInvestigations", index: number, key: string, value: any) => setForm(current => ({ ...current, [section]: (current[section] as any[]).map((item, itemIndex) => itemIndex === index ? { ...item, [key]: value } : item) }));
  const remove = (section: "radiologicalInvestigations" | "laboratoryInvestigations" | "neurologicalInvestigations" | "followUpVisits", index: number) => setForm(current => ({ ...current, [section]: (current[section] as any[]).filter((_, itemIndex) => itemIndex !== index) }));
  const upload = async (event: React.ChangeEvent<HTMLInputElement>) => { const selected = event.target.files?.[0]; event.target.value = ""; if (!selected || !recordId) return toast.error("Save the record before uploading files."); const allowed = ["application/pdf", "application/dicom", "image/jpeg", "image/png", "image/webp", "image/tiff", "text/plain"]; if (!allowed.includes(selected.type) || selected.size > 15 * 1024 * 1024) return toast.error("Use an approved file type up to 15 MB."); const bytes = new Uint8Array(await selected.arrayBuffer()); let binary = ""; bytes.forEach(byte => { binary += String.fromCharCode(byte); }); const ext = selected.name.split(".").pop()?.replace(/[^a-z0-9]/gi, "") || "bin"; uploadFile.mutate({ patientRecordId: recordId, fileName: `MUNR-FILE-${Date.now()}.${ext}`, mimeType: selected.type as any, sizeBytes: bytes.byteLength, category: fileCategory, contentBase64: btoa(binary) }); };
  if (mode === "edit" && isLoading) return <EditorLoading />; if (mode === "edit" && (error || !record)) return <div className="rounded-xl border border-rose-200 bg-rose-50 p-6 text-sm text-rose-700">This record could not be loaded. {error?.message}</div>;
  return <div className="mx-auto max-w-7xl space-y-6 fade-rise"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><Button variant="ghost" onClick={() => navigate("/registry")} className="-ml-3 text-slate-500"><ArrowLeft className="mr-2 h-4 w-4" />Back to registry</Button><h1 className="mt-2 font-display text-3xl text-[#172b38]">{mode === "create" ? "New neurology research record" : form.researchId}</h1><p className="mt-2 text-sm text-slate-500">Mansoura University Neurology Research Registry · pseudonymised record only</p></div><Button onClick={submit} disabled={create.isPending || update.isPending} className="bg-[#125d69] hover:bg-[#0d4b55]"><Save className="mr-2 h-4 w-4" />Save record</Button></div><div className="grid gap-6 xl:grid-cols-[1fr_300px]"><div className="space-y-6"><PrivacyNotice /><PathwaySnapshot cohort={form.cohort} items={form.protocolInvestigations} /><Panel icon={ClipboardCheck} eyebrow="RESEARCH IDENTITY" title="Core patient record"><div className="grid gap-4 md:grid-cols-2"><TextField label="Research ID" hint="Format: MUNR-XXXX"><Input value={form.researchId} onChange={event => set("researchId", event.target.value.toUpperCase())} placeholder="MUNR-2026A" /></TextField><SelectField label="Neurology cohort" value={form.cohort} onChange={value => setCohort(value as Cohort)} options={Object.entries(cohorts)} /><TextField label="Primary diagnosis"><Input value={form.primaryDiagnosis} onChange={event => set("primaryDiagnosis", event.target.value)} placeholder="e.g., Ischaemic stroke" /></TextField><SelectField label="Sex" value={form.sex} onChange={value => set("sex", value as FormState["sex"])} options={[["female", "Female"], ["male", "Male"], ["not_recorded", "Not recorded"]]} /><TextField label="Age at enrolment"><Input type="number" value={form.ageAtEnrollment} onChange={event => set("ageAtEnrollment", event.target.value)} /></TextField><TextField label="Age at onset" hint="Optional"><Input type="number" value={form.ageAtOnset} onChange={event => set("ageAtOnset", event.target.value)} /></TextField></div></Panel><NarrativeSection form={form} set={set} /><Panel icon={CheckCircle2} eyebrow="COMPLETION WORKFLOW" title="Record completeness and accountability"><div className="grid gap-4 md:grid-cols-2"><SelectField label="Completeness status" value={form.completenessStatus} onChange={value => set("completenessStatus", value as FormState["completenessStatus"])} options={[["incomplete", "Incomplete"], ["needs_review", "Needs review"], ["complete", "Complete"]]} /><SelectField label="Assigned completion owner" value={form.completionOwnerUserId} onChange={value => set("completionOwnerUserId", value)} options={[["unassigned", "Unassigned"], ...owners.map(owner => [String(owner.id), owner.name || `User ${owner.id}`] as Choice)]} /><div className="md:col-span-2"><Label>Items still required</Label><div className="mt-2 grid gap-2 sm:grid-cols-2">{missingItemChoices.map(([value, label]) => <label key={value} className="flex items-center gap-2 rounded-lg border border-[#e0e9e5] bg-[#fbfdfc] px-3 py-2 text-sm text-slate-600"><input type="checkbox" checked={form.missingItems.includes(value)} onChange={event => set("missingItems", event.target.checked ? [...form.missingItems, value] : form.missingItems.filter(item => item !== value))} />{label}</label>)}</div></div></div></Panel><Panel icon={ShieldCheck} eyebrow="STUDY GOVERNANCE" title="Consent and enrolment"><div className="grid gap-4 md:grid-cols-2"><SelectField label="Consent" value={form.consentStatus} onChange={value => set("consentStatus", value as FormState["consentStatus"])} options={[["consented", "Consented"], ["pending", "Pending"], ["declined", "Declined"], ["withdrawn", "Withdrawn"]]} /><SelectField label="Enrolment" value={form.enrollmentStatus} onChange={value => set("enrollmentStatus", value as FormState["enrollmentStatus"])} options={[["screened", "Screened"], ["enrolled", "Enrolled"], ["completed", "Completed"], ["withdrawn", "Withdrawn"], ["ineligible", "Ineligible"]]} /><SelectField label="Clinical status" value={form.clinicalStatus} onChange={value => set("clinicalStatus", value as FormState["clinicalStatus"])} options={[["active", "Active"], ["follow_up", "Follow-up"], ["completed", "Completed"], ["deceased", "Deceased"], ["unknown", "Unknown"]]} /><SelectField label="Data quality" value={form.dataQualityStatus} onChange={value => set("dataQualityStatus", value as FormState["dataQualityStatus"])} options={[["draft", "Draft"], ["complete", "Complete"], ["query", "Query"]]} /></div></Panel><ClinicalSection cohort={form.cohort} data={form.clinicalData} setData={(key, value) => set("clinicalData", { ...form.clinicalData, [key]: value })} />{immuneCohorts.includes(form.cohort) && <ImmuneTherapySection items={form.immuneTherapies} setItems={items => set("immuneTherapies", items)} />}{form.cohort === "multiple_sclerosis" && <DoseAdherenceSection items={form.msDoseAdherence} setItems={items => set("msDoseAdherence", items)} />}<ProtocolSection items={form.protocolInvestigations} update={(index, key, value) => updateArray("protocolInvestigations", index, key, value)} /><InvestigationSection title="Radiological investigations" icon={FileImage} items={form.radiologicalInvestigations} kind="radiology" add={() => add("radiologicalInvestigations")} update={(i, key, value) => updateArray("radiologicalInvestigations", i, key, value)} remove={i => remove("radiologicalInvestigations", i)} /><InvestigationSection title="Laboratory investigations" icon={FlaskConical} items={form.laboratoryInvestigations} kind="laboratory" add={() => add("laboratoryInvestigations")} update={(i, key, value) => updateArray("laboratoryInvestigations", i, key, value)} remove={i => remove("laboratoryInvestigations", i)} /><InvestigationSection title="Neurological investigations" icon={ListChecks} items={form.neurologicalInvestigations} kind="neurological" add={() => add("neurologicalInvestigations")} update={(i, key, value) => updateArray("neurologicalInvestigations", i, key, value)} remove={i => remove("neurologicalInvestigations", i)} /><FollowUpSection items={form.followUpVisits} add={() => add("followUpVisits")} update={(i, key, value) => updateArray("followUpVisits", i, key, value)} remove={i => remove("followUpVisits", i)} /><FilesSection recordId={recordId} files={files as ResearchFile[]} category={fileCategory} setCategory={setFileCategory} onUpload={upload} isUploading={uploadFile.isPending} /></div><aside className="space-y-4"><ResearchIdCard researchId={form.researchId} cohort={form.cohort} status={form.completenessStatus} /><Card className="border-[#dce9e5] bg-[#f0f8f6]"><CardContent className="p-5"><p className="text-xs font-bold tracking-[0.13em] text-[#34736c]">DATA MINIMISATION</p><p className="mt-3 text-sm leading-6 text-[#426364]">Do not enter names, contact details, national IDs, addresses, hospital identifiers, or exact dates outside protocol-specified treatment and adherence dates.</p></CardContent></Card>{mode === "edit" && <AuditPanel audit={audit} />}</aside></div></div>;
}

function Panel({ icon: Icon, eyebrow, title, children }: { icon: typeof ClipboardCheck; eyebrow: string; title: string; children: React.ReactNode }) { return <Card className="border-[#e1e9e5] shadow-sm"><CardContent className="p-6"><div className="mb-6 flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#edf7f4] text-[#2e716b]"><Icon className="h-4 w-4" /></span><div><p className="text-[10px] font-bold tracking-[0.13em] text-[#63807b]">{eyebrow}</p><h2 className="mt-0.5 font-display text-xl text-[#203943]">{title}</h2></div></div>{children}</CardContent></Card>; }
function PathwaySnapshot({ cohort, items }: { cohort: Cohort; items: ProtocolInvestigation[] }) { const highlights: Record<Cohort, string[]> = { stroke: ["Stroke complications", "NIHSS / mRS", "Discharge treatment"], multiple_sclerosis: ["Tuberculin & chest TB screen", "Dose adherence by date", "MSFC & DMT"], abnormal_movements: ["Phenomenology evaluation", "Functional impact", "Targeted testing"], guillain_barre: ["Respiratory status", "Disability score", "Immune therapy"], myasthenia_gravis: ["MGFA / QMG", "Antibody pathway", "Immune therapy"], myelopathy: ["MRI & neuro-exam", "Inflammatory pathway", "Targeted testing"], neuro_ophthalmology: ["NMOSD · MOGAD · GCA", "AQP4 / MOG profile", "OCT & systemic linkage"], cidp: ["Typical CIDP & MADSAM", "Mononeuritis / vasculitic pathway", "EMG/NCS & immune therapy"] }; return <div className="overflow-hidden rounded-2xl border border-[#c8e3dc] bg-[linear-gradient(120deg,#eef9f6_0%,#f8fcfb_62%,#e8f2fa_100%)] p-5"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-[10px] font-bold tracking-[0.14em] text-[#36766f]">ACTIVE CLINICAL PATHWAY</p><h2 className="mt-1 font-display text-2xl text-[#1d4b50]">{cohorts[cohort]}</h2></div><span className="rounded-full border border-[#b9ded4] bg-white/70 px-3 py-1 text-xs font-medium text-[#276a64]">{items.length} protocol items</span></div><div className="mt-4 grid gap-2 sm:grid-cols-3">{highlights[cohort].map(item => <div key={item} className="rounded-xl border border-[#b9ded4] bg-white/90 px-3 py-2 text-xs font-semibold text-[#276a64]">{item}</div>)}</div><div className="mt-3 flex flex-wrap gap-2">{items.map(item => <span key={item.itemCode} className="rounded-lg border border-[#d5e9e3] bg-white/80 px-2.5 py-1.5 text-xs text-[#416363]">{protocolLabels[item.itemCode] || item.itemCode}</span>)}</div></div>; }
function TextField({ label, hint, children }: { label: string; hint?: string; children: React.ReactNode }) { return <div><div className="mb-1.5 flex items-center justify-between"><Label>{label}</Label>{hint && <span className="text-[11px] text-slate-400">{hint}</span>}</div>{children}</div>; }
function SelectField({ label, value, onChange, options }: { label: string; value: string; onChange: (value: string) => void; options: Choice[] }) { return <TextField label={label}><Select value={value} onValueChange={onChange}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{options.map(([key, text]) => <SelectItem key={key} value={key}>{text}</SelectItem>)}</SelectContent></Select></TextField>; }
function NarrativeSection({ form, set }: { form: FormState; set: <K extends keyof FormState>(key: K, value: FormState[K]) => void }) { return <Panel icon={ClipboardCheck} eyebrow="CLINICAL NARRATIVE" title="History, examination and discharge treatment"><p className="mb-5 text-sm text-slate-500">Use concise, research-safe summaries. Do not enter direct identifiers.</p><div className="grid gap-4"><TextField label="Brief clinical history"><Textarea value={form.briefClinicalHistory} onChange={event => set("briefClinicalHistory", event.target.value)} placeholder="Presenting syndrome, onset pattern and relevant course." /></TextField><TextField label="Positive examination findings"><Textarea value={form.positiveExaminationFindings} onChange={event => set("positiveExaminationFindings", event.target.value)} placeholder="Positive neurological findings only." /></TextField><TextField label="Discharge treatment"><Textarea value={form.dischargeTreatment} onChange={event => set("dischargeTreatment", event.target.value)} placeholder="Research-safe summary of treatment at discharge." /></TextField></div></Panel>; }
function ClinicalSection({ cohort, data, setData }: { cohort: Cohort; data: Record<string, string>; setData: (key: string, value: string) => void }) {
  const common: Record<Cohort, Choice[]> = { stroke: [["strokeType", "Stroke type"], ["vascularTerritory", "Vascular territory"], ["reperfusionTherapy", "Reperfusion therapy"], ["toastEtiology", "TOAST aetiology"], ["majorComplication", "Stroke complication"], ["strokeEvaluation", "Stroke evaluation"]], multiple_sclerosis: [["diseaseCourse", "Disease course"], ["disabilityLevel", "Disability level"], ["relapseActivity", "Relapse activity"], ["diseaseModifyingTherapy", "Disease-modifying therapy"], ["msfcAssessed", "MSFC assessed"], ["tuberculinScreen", "Tuberculin / IGRA screen"], ["chestTuberculosisScreen", "Chest tuberculosis screen"], ["msEvaluation", "MS evaluation"]], abnormal_movements: [["movementPhenotype", "Movement phenotype"], ["distribution", "Distribution"], ["severity", "Severity"], ["functionalImpact", "Functional impact"], ["treatmentResponse", "Treatment response"], ["movementEvaluation", "Movement evaluation"]], guillain_barre: [["variant", "GBS variant"], ["disabilityScore", "Disability score"], ["ventilatorySupport", "Ventilatory support"], ["treatment", "Treatment"], ["gbsEvaluation", "GBS evaluation"]], myasthenia_gravis: [["mgfaClass", "MGFA class"], ["antibodyStatus", "Antibody status"], ["thymomaStatus", "Thymoma status"], ["crisisHistory", "Crisis history"], ["treatmentResponse", "Treatment response"], ["mgEvaluation", "MG evaluation"]], myelopathy: [["level", "Spinal level"], ["cause", "Likely cause"], ["upperMotorNeuronSigns", "UMN signs"], ["lowerMotorNeuronFeatures", "LMN features"], ["bladderInvolvement", "Bladder involvement"], ["myelopathyEvaluation", "Myelopathy evaluation"]], neuro_ophthalmology: [["visualSyndrome", "Visual syndrome"], ["laterality", "Laterality"], ["acuityChange", "Acuity change"], ["afferentDefect", "Afferent defect"], ["diseaseClassification", "Disease classification"], ["antibodyProfile", "AQP4 / MOG profile"], ["linkedSystemicDisease", "Linked systemic disease"], ["neuroOphEvaluation", "Neuro-ophthalmology evaluation"]], cidp: [["phenotype", "CIDP variant"], ["diagnosticPathway", "Diagnostic pathway"], ["disabilityLevel", "Disability level"], ["emgNcsEvidence", "EMG/NCS evidence"], ["csfProteinStatus", "CSF protein status"], ["cidpEvaluation", "CIDP / neuropathy evaluation"]] };
  const options = (key: string): Choice[] => { const map: Record<string, Choice[]> = { vascularTerritory: [["aca", "ACA"], ["mca_complete", "MCA complete"], ["mca_incomplete", "MCA incomplete"], ["pca", "PCA"], ["vertebrobasilar", "Vertebrobasilar"], ["other", "Other"], ["unknown", "Unknown"]], majorComplication: [["none", "None"], ["hemorrhagic_transformation", "Haemorrhagic transformation"], ["cerebral_edema", "Cerebral oedema"], ["seizure", "Seizure"], ["aspiration_pneumonia", "Aspiration pneumonia"], ["dvt_pe", "DVT / pulmonary embolism"], ["recurrent_stroke", "Recurrent stroke"], ["other", "Other"], ["unknown", "Unknown"]], strokeEvaluation: [["nihss_and_mrs", "NIHSS and mRS"], ["nihss_only", "NIHSS only"], ["mrs_only", "mRS only"], ["not_recorded", "Not recorded"], ["unknown", "Unknown"]], diseaseModifyingTherapy: [["none", "None"], ["interferon_beta", "Interferon beta"], ["glatiramer_acetate", "Glatiramer acetate"], ["dimethyl_fumarate", "Dimethyl fumarate"], ["teriflunomide", "Teriflunomide"], ["fingolimod", "Fingolimod"], ["siponimod", "Siponimod"], ["natalizumab", "Natalizumab"], ["ocrelizumab", "Ocrelizumab"], ["ofatumumab", "Ofatumumab"], ["cladribine", "Cladribine"], ["alemtuzumab", "Alemtuzumab"], ["other", "Other"], ["unknown", "Unknown"]], msfcAssessed: [["yes", "Yes"], ["no", "No"], ["not_applicable", "Not applicable"]], tuberculinScreen: [["negative", "Negative"], ["positive", "Positive"], ["indeterminate", "Indeterminate"], ["not_done", "Not done"], ["not_required", "Not required"], ["unknown", "Unknown"]], chestTuberculosisScreen: [["clear", "Clear"], ["abnormal", "Abnormal"], ["not_done", "Not done"], ["not_required", "Not required"], ["unknown", "Unknown"]], msEvaluation: [["clinical_mri_msfc", "Clinical, MRI and MSFC"], ["clinical_mri", "Clinical and MRI"], ["clinical_only", "Clinical only"], ["treatment_safety", "Treatment-safety review"], ["unknown", "Unknown"]], movementEvaluation: [["phenomenology_and_video", "Phenomenology and video"], ["phenomenology_only", "Phenomenology only"], ["imaging_reviewed", "Imaging reviewed"], ["unknown", "Unknown"]], gbsEvaluation: [["gbs_disability_and_respiratory", "Disability and respiratory"], ["gbs_disability_only", "Disability score only"], ["electrodiagnostic_reviewed", "Electrodiagnostic review"], ["unknown", "Unknown"]], mgEvaluation: [["mgfa_and_qmg", "MGFA and QMG"], ["mgfa_only", "MGFA only"], ["respiratory_review", "Respiratory review"], ["unknown", "Unknown"]], myelopathyEvaluation: [["mri_and_neuroexam", "MRI and neurological exam"], ["mri_only", "MRI only"], ["csf_reviewed", "CSF reviewed"], ["unknown", "Unknown"]], diseaseClassification: [["nmosd", "NMOSD"], ["mogad", "MOGAD"], ["giant_cell_arteritis", "Giant cell arteritis (GCA)"], ["ms_associated", "MS-associated"], ["idiopathic_optic_neuritis", "Idiopathic optic neuritis"], ["other", "Other"], ["unknown", "Unknown"]], antibodyProfile: [["aqp4_positive", "AQP4 positive"], ["mog_positive", "MOG positive"], ["both_negative", "Both negative"], ["not_done", "Not done"], ["unknown", "Unknown"]], linkedSystemicDisease: [["none", "None"], ["multiple_sclerosis", "Multiple sclerosis"], ["sarcoidosis", "Sarcoidosis"], ["systemic_vasculitis", "Systemic vasculitis"], ["other", "Other"], ["unknown", "Unknown"]], neuroOphEvaluation: [["acuity_fields_oct", "Acuity, fields and OCT"], ["fundus_and_oct", "Fundus and OCT"], ["antibody_workup", "Antibody work-up"], ["gca_pathway", "GCA pathway"], ["unknown", "Unknown"]], phenotype: [["typical", "Typical CIDP"], ["madsam", "MADSAM / multifocal"], ["distal", "Distal CIDP"], ["focal", "Focal CIDP"], ["motor", "Motor CIDP"], ["sensory", "Sensory CIDP"], ["other", "Other"], ["unknown", "Unknown"]], diagnosticPathway: [["cidp", "CIDP"], ["mononeuritis_multiplex", "Mononeuritis multiplex"], ["vasculitic_neuropathy", "Vasculitic neuropathy"], ["other", "Other"], ["unknown", "Unknown"]], emgNcsEvidence: [["demyelinating", "Demyelinating"], ["axonal_multifocal", "Axonal multifocal"], ["equivocal", "Equivocal"], ["not_done", "Not done"], ["unknown", "Unknown"]], cidpEvaluation: [["emg_ncs_and_disability", "EMG/NCS and disability"], ["emg_ncs_only", "EMG/NCS only"], ["vasculitis_workup", "Vasculitis work-up"], ["unknown", "Unknown"]] }; if (map[key]) return map[key]; return [["present", "Present"], ["absent", "Absent"], ["yes", "Yes"], ["no", "No"], ["mild", "Mild"], ["moderate", "Moderate"], ["severe", "Severe"], ["active", "Active"], ["inactive", "Inactive"], ["responsive", "Responsive"], ["partially_responsive", "Partially responsive"], ["refractory", "Refractory"], ["ischemic", "Ischaemic"], ["hemorrhagic", "Haemorrhagic"], ["tia", "TIA"], ["aidp", "AIDP"], ["aman", "AMAN"], ["amsan", "AMSAN"], ["miller_fisher", "Miller Fisher"], ["I", "Class I"], ["II", "Class II"], ["III", "Class III"], ["IV", "Class IV"], ["V", "Class V"], ["unknown", "Unknown"], ["other", "Other"]]; };
  return <Panel icon={ClipboardCheck} eyebrow="COHORT-SPECIFIC DATA" title={cohorts[cohort]}><div className="grid gap-4 md:grid-cols-2">{common[cohort].map(([key, label]) => <SelectField key={key} label={label} value={data[key] || "unknown"} onChange={value => setData(key, value)} options={options(key)} />)}{cohort === "multiple_sclerosis" && <><TextField label="Timed 25-Foot Walk (seconds)"><Input type="number" value={data.timed25FootWalkSeconds || ""} onChange={event => setData("timed25FootWalkSeconds", event.target.value)} /></TextField><TextField label="9-Hole Peg Test (seconds)"><Input type="number" value={data.nineHolePegTestSeconds || ""} onChange={event => setData("nineHolePegTestSeconds", event.target.value)} /></TextField><TextField label="PASAT-3 score"><Input type="number" value={data.pasat3Score || ""} onChange={event => setData("pasat3Score", event.target.value)} /></TextField></>}</div></Panel>;
}
function ImmuneTherapySection({ items, setItems }: { items: ImmuneTherapy[]; setItems: (items: ImmuneTherapy[]) => void }) { const update = (index: number, key: keyof ImmuneTherapy, value: string) => setItems(items.map((item, itemIndex) => itemIndex === index ? { ...item, [key]: value } : item)); const add = () => setItems([...items, { therapyClass: "corticosteroid", agent: null, status: "planned", startDate: null, infectionExclusionStatus: "not_assessed", infectionExclusionNote: null, note: null }]); return <Panel icon={Pill} eyebrow="IMMUNE THERAPY" title="Immune therapy capture"><p className="mb-5 text-sm text-slate-500">Shown only for cohorts where immune therapy may be relevant. The cohort protocol now lists chest imaging, tuberculin/IGRA TB screening, and varicella immunity review where appropriate; the treating team decides which investigations apply to an individual case.</p><Button variant="outline" type="button" onClick={add}><Plus className="mr-2 h-4 w-4" />Add immune therapy</Button><div className="mt-4 space-y-3">{items.length === 0 && <p className="rounded-xl border border-dashed p-5 text-center text-sm text-slate-500">No immune therapy recorded.</p>}{items.map((item, index) => <div key={index} className="grid gap-3 rounded-xl border border-[#e1e9e5] bg-[#fbfdfc] p-4 md:grid-cols-2"><SelectField label="Therapy class" value={item.therapyClass} onChange={value => update(index, "therapyClass", value)} options={[["corticosteroid", "Corticosteroid"], ["ivig", "IVIg"], ["scig", "SCIg"], ["plasma_exchange", "Plasma exchange"], ["b_cell_depleting", "B-cell depleting"], ["immunosuppressant", "Immunosuppressant"], ["biologic", "Biologic"], ["other", "Other"]]} /><SelectField label="Status" value={item.status} onChange={value => update(index, "status", value)} options={[["planned", "Planned"], ["active", "Active"], ["completed", "Completed"], ["discontinued", "Discontinued"], ["unknown", "Unknown"]]} /><TextField label="Agent" hint="Optional"><Input value={item.agent ?? ""} onChange={event => update(index, "agent", event.target.value)} placeholder="e.g., IVIg" /></TextField><TextField label="Start / administration date" hint="Optional"><Input type="date" value={item.startDate ?? ""} onChange={event => update(index, "startDate", event.target.value)} /></TextField><SelectField label="Infection-exclusion status before immune therapy" value={item.infectionExclusionStatus ?? "not_assessed"} onChange={value => update(index, "infectionExclusionStatus", value)} options={[["not_assessed", "Not assessed"], ["cleared", "Cleared in protocol review"], ["positive_or_suspected", "Positive or suspected finding"], ["referred", "Referred for review"], ["not_indicated", "Not indicated"], ["unknown", "Unknown"]]} /><TextField label="Infection-exclusion note" hint="Optional"><Input value={item.infectionExclusionNote ?? ""} onChange={event => update(index, "infectionExclusionNote", event.target.value)} placeholder="Research-safe protocol note only" /></TextField><div className="md:col-span-2"><TextField label="Research-safe note" hint="Optional"><Input value={item.note ?? ""} onChange={event => update(index, "note", event.target.value)} /></TextField></div><Button variant="ghost" size="sm" className="justify-self-start text-rose-600" onClick={() => setItems(items.filter((_, itemIndex) => itemIndex !== index))}><Trash2 className="mr-1 h-3.5 w-3.5" />Remove</Button></div>)}</div></Panel>; }
function DoseAdherenceSection({ items, setItems }: { items: MultipleSclerosisDoseAdherence[]; setItems: (items: MultipleSclerosisDoseAdherence[]) => void }) { const update = (index: number, key: keyof MultipleSclerosisDoseAdherence, value: string) => setItems(items.map((item, itemIndex) => itemIndex === index ? { ...item, [key]: value } : item)); return <Panel icon={Pill} eyebrow="MS TREATMENT ADHERENCE" title="Dose compliance by date"><p className="mb-5 text-sm text-slate-500">Record a dated dose event for MS disease-modifying therapy adherence.</p><Button variant="outline" type="button" onClick={() => setItems([...items, { therapyName: "", doseDate: "", doseStatus: "unknown", reason: null }])}><Plus className="mr-2 h-4 w-4" />Add dose event</Button><div className="mt-4 space-y-3">{items.length === 0 && <p className="rounded-xl border border-dashed p-5 text-center text-sm text-slate-500">No dated dose events recorded.</p>}{items.map((item, index) => <div key={index} className="grid gap-3 rounded-xl border border-[#e1e9e5] bg-[#fbfdfc] p-4 md:grid-cols-2"><TextField label="DMT / therapy"><Input value={item.therapyName} onChange={event => update(index, "therapyName", event.target.value)} placeholder="e.g., Ocrelizumab" /></TextField><TextField label="Dose date"><Input type="date" value={item.doseDate} onChange={event => update(index, "doseDate", event.target.value)} /></TextField><SelectField label="Dose status" value={item.doseStatus} onChange={value => update(index, "doseStatus", value)} options={[["taken", "Taken"], ["missed", "Missed"], ["delayed", "Delayed"], ["unknown", "Unknown"]]} /><TextField label="Reason" hint="Optional"><Input value={item.reason ?? ""} onChange={event => update(index, "reason", event.target.value)} /></TextField><Button variant="ghost" size="sm" className="justify-self-start text-rose-600" onClick={() => setItems(items.filter((_, itemIndex) => itemIndex !== index))}><Trash2 className="mr-1 h-3.5 w-3.5" />Remove</Button></div>)}</div></Panel>; }
function ProtocolSection({ items, update }: { items: ProtocolInvestigation[]; update: (index: number, key: string, value: string) => void }) { return <Panel icon={ListChecks} eyebrow="COHORT PROTOCOL" title="Recommended investigations"><p className="mb-5 text-sm text-slate-500">This checklist supports consistent research capture. Clinical teams determine whether each item is appropriate for an individual case.</p><div className="space-y-3">{items.map((item, index) => <div key={`${item.itemCode}-${index}`} className="grid gap-3 rounded-xl border border-[#e1e9e5] bg-[#fbfdfc] p-4 md:grid-cols-[1fr_180px]"><div><p className="text-sm font-medium text-[#29464d]">{protocolLabels[item.itemCode] || item.itemCode}</p><Input className="mt-2" value={item.note ?? ""} onChange={event => update(index, "note", event.target.value)} placeholder="Optional research-safe note" /></div><Select value={item.status} onValueChange={value => update(index, "status", value)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="not_ordered">Not ordered</SelectItem><SelectItem value="ordered">Ordered</SelectItem><SelectItem value="completed">Completed</SelectItem><SelectItem value="not_indicated">Not indicated</SelectItem></SelectContent></Select></div>)}</div></Panel>; }
function InvestigationSection({ title, icon, items, kind, add, update, remove }: { title: string; icon: typeof FileImage; items: any[]; kind: "radiology" | "laboratory" | "neurological"; add: () => void; update: (index: number, key: string, value: any) => void; remove: (index: number) => void }) { const tests: Choice[] = kind === "laboratory" ? [["hba1c", "HbA1c"], ["uric_acid", "Uric acid"], ["lipid_profile", "Lipid profile"], ["thyroid_function", "Thyroid function"], ["ck", "CK"], ["b12_folate", "B12 / folate"], ["electrolytes", "Electrolytes"], ["inflammatory_markers", "Inflammatory markers"], ["autoimmune_panel", "Autoimmune panel"], ["esr_crp", "ESR / CRP"], ["hepatitis_screening", "Hepatitis screening"], ["varicella_immunity", "Varicella immunity (VZV immunoglobulin / serology)"], ["renal_profile", "Renal profile"], ["other", "Other"]] : [["emg_ncs", "EMG / NCS"], ["csf_analysis", "CSF analysis"], ["fundus_examination", "Fundus examination"], ["eeg", "EEG"], ["evoked_potentials", "Evoked potentials"], ["genetic_testing", "Genetic testing"], ["cognitive_assessment", "Cognitive assessment"], ["temporal_artery_assessment", "Temporal artery assessment"], ["nerve_biopsy", "Nerve biopsy"], ["aqp4_mog_antibodies", "AQP4 / MOG antibodies"], ["other", "Other"]]; const statuses: Choice[] = [["normal", "Normal"], ["abnormal", "Abnormal"], ["borderline", "Borderline"], ["not_done", "Not done"], ["unknown", "Unknown"]]; return <Panel icon={icon} eyebrow="INVESTIGATIONS" title={title}><Button variant="outline" type="button" onClick={add}><Plus className="mr-2 h-4 w-4" />Add item</Button><div className="mt-4 space-y-3">{items.length === 0 && <p className="rounded-xl border border-dashed p-5 text-center text-sm text-slate-500">No items recorded.</p>}{items.map((item, index) => <div key={index} className="rounded-xl border border-[#e1e9e5] bg-[#fbfdfc] p-4"><div className="mb-3 flex justify-end"><Button variant="ghost" size="sm" className="text-rose-600" onClick={() => remove(index)}><Trash2 className="mr-1 h-3.5 w-3.5" />Remove</Button></div>{kind === "radiology" ? <div className="grid gap-3 md:grid-cols-2"><SelectField label="Modality" value={item.modality} onChange={value => update(index, "modality", value)} options={[["mri", "MRI"], ["ct", "CT"], ["cta", "CTA"], ["mra", "MRA"], ["dsa", "DSA"], ["doppler", "Doppler"], ["pet", "PET"], ["spect", "SPECT"], ["xray", "X-ray"], ["other", "Other"]]} /><SelectField label="Region" value={item.bodyRegion} onChange={value => update(index, "bodyRegion", value)} options={[["brain", "Brain"], ["spine", "Spine"], ["chest", "Chest"], ["cranial_nerves", "Cranial nerves"], ["cerebral_vessels", "Cerebral vessels"], ["temporal_arteries", "Temporal arteries"], ["peripheral_nerves", "Peripheral nerves"], ["other", "Other"]]} /><TextField label="Key finding"><Input value={item.keyFinding} onChange={event => update(index, "keyFinding", event.target.value)} /></TextField><SelectField label="Lesion status" value={item.lesionStatus} onChange={value => update(index, "lesionStatus", value)} options={[["present", "Present"], ["absent", "Absent"], ["indeterminate", "Indeterminate"], ["not_applicable", "Not applicable"]]} /></div> : <div className="grid gap-3 md:grid-cols-2"><SelectField label="Test" value={item.testName} onChange={value => update(index, "testName", value)} options={tests} /><SelectField label="Result" value={item.resultStatus} onChange={value => update(index, "resultStatus", value)} options={statuses} /><TextField label="Result summary"><Input value={item.resultSummary ?? ""} onChange={event => update(index, "resultSummary", event.target.value)} /></TextField>{kind === "neurological" && <label className="flex items-center gap-2 self-end text-sm text-slate-600"><input type="checkbox" checked={Boolean(item.lowerMotorNeuronRelevant)} onChange={event => update(index, "lowerMotorNeuronRelevant", event.target.checked)} />Relevant to lower motor neuron assessment</label>}</div>}</div>)}</div></Panel>; }
function FollowUpSection({ items, add, update, remove }: { items: PatientFollowUp[]; add: () => void; update: (index: number, key: string, value: string) => void; remove: (index: number) => void }) { return <Panel icon={ClipboardCheck} eyebrow="LONGITUDINAL DATA" title="Patient follow-up"><Button variant="outline" type="button" onClick={add}><Plus className="mr-2 h-4 w-4" />Add follow-up</Button><div className="mt-4 space-y-3">{items.map((item, index) => <div key={index} className="grid gap-3 rounded-xl border border-[#e1e9e5] bg-[#fbfdfc] p-4 md:grid-cols-2"><SelectField label="Visit type" value={item.visitType} onChange={value => update(index, "visitType", value)} options={[["baseline", "Baseline"], ["routine", "Routine"], ["post_discharge", "Post-discharge"], ["emergency", "Emergency"], ["telemedicine", "Telemedicine"], ["other", "Other"]]} /><SelectField label="Follow-up status" value={item.followUpStatus} onChange={value => update(index, "followUpStatus", value)} options={[["completed", "Completed"], ["scheduled", "Scheduled"], ["missed", "Missed"], ["lost_to_follow_up", "Lost to follow-up"], ["withdrawn", "Withdrawn"]]} /><TextField label="Assessment summary"><Input value={item.assessmentSummary} onChange={event => update(index, "assessmentSummary", event.target.value)} /></TextField><Button variant="ghost" size="sm" className="self-end text-rose-600" onClick={() => remove(index)}><Trash2 className="mr-1 h-3.5 w-3.5" />Remove</Button></div>)}</div></Panel>; }
function FilesSection({ recordId, files, category, setCategory, onUpload, isUploading }: { recordId?: number; files: ResearchFile[]; category: "radiology_image" | "radiology_report" | "laboratory_report" | "other"; setCategory: (value: "radiology_image" | "radiology_report" | "laboratory_report" | "other") => void; onUpload: (event: React.ChangeEvent<HTMLInputElement>) => void; isUploading: boolean }) { return <Panel icon={FileUp} eyebrow="SECURE FILES" title="Research files"><div className="grid gap-3 md:grid-cols-2"><SelectField label="Category" value={category} onChange={value => setCategory(value as typeof category)} options={[["radiology_image", "Radiology image"], ["radiology_report", "Radiology report"], ["laboratory_report", "Laboratory report"], ["other", "Other"]]} /><TextField label="Upload file" hint="Approved types · max 15 MB"><Input type="file" disabled={!recordId || isUploading} onChange={onUpload} accept="application/pdf,application/dicom,image/jpeg,image/png,image/webp,image/tiff,text/plain" /></TextField></div><div className="mt-4 space-y-2">{!recordId ? <p className="text-sm text-slate-500">Save the record before uploading files.</p> : files.map(file => <div key={file.storageKey} className="flex items-center gap-3 rounded-lg border border-[#e1e9e5] p-3 text-sm"><FileUp className="h-4 w-4 text-[#2e716b]" /><span className="min-w-0 flex-1 truncate">{file.fileName}</span><Badge variant="outline">{file.category.replace(/_/g, " ")}</Badge></div>)}</div></Panel>; }
function ResearchIdCard({ researchId, cohort, status }: { researchId: string; cohort: Cohort; status: string }) { return <Card className="border-[#dce9e5]"><CardContent className="p-5"><p className="text-xs font-bold tracking-[0.13em] text-[#68807d]">MANSOURA UNIVERSITY</p><p className="mt-2 font-display text-2xl text-[#1f4148]">{researchId || "MUNR-XXXX"}</p><p className="mt-3 text-xs text-slate-500">{cohorts[cohort]}</p><Badge className="mt-3 bg-[#eef7f4] text-[#2d716a] hover:bg-[#eef7f4]">{status.replace(/_/g, " ")}</Badge></CardContent></Card>; }
function PrivacyNotice() { return <div className="flex gap-3 rounded-xl border border-[#bcded7] bg-[#eaf7f3] p-4 text-sm text-[#1f5d57]"><Info className="mt-0.5 h-4 w-4 shrink-0" /><p><strong>Privacy checkpoint:</strong> record only the study-generated MUNR Research ID. Never enter a patient name, phone number, national ID, address, hospital identifier, or exact date unrelated to treatment and dose adherence.</p></div>; }
function AuditPanel({ audit }: { audit: any[] | undefined }) { return <Card className="border-[#e1e9e5]"><CardContent className="p-5"><p className="text-xs font-bold tracking-[0.13em] text-[#68807d]">AUDIT TRAIL</p><div className="mt-4 space-y-4">{audit?.length ? audit.map(item => <div key={item.id} className="border-l-2 border-[#99cfc4] pl-3"><p className="text-xs font-semibold capitalize text-[#2e5960]">{item.action}</p><p className="mt-1 text-xs leading-5 text-slate-500">{item.fieldSummary}</p></div>) : <p className="text-xs text-slate-500">No activity recorded.</p>}</div></CardContent></Card>; }
function EditorLoading() { return <div className="mx-auto max-w-6xl space-y-6"><Skeleton className="h-20 w-full" /><Skeleton className="h-72 w-full" /><Skeleton className="h-72 w-full" /></div>; }
